(1,'Theme Custom','theme-custom','arrows','.theme-custom.tparrows {\n	cursor:pointer;\n	background:#000;\n	background: ##background##;\n	width: ##width##px;\n	height: ##height##px;\n	position:absolute;\n	display:flex;\n  	align-items: center;\n  	justify-content: center;\n	z-index:1000;\n  	color: ##icon_color##;\n  	transition: all 300ms ease 0s;\n}\n.theme-custom.tparrows.rs-touchhover {\n	background: ##hover_bg##;\n    color: ##hover_color##;\n}\n.theme-custom.tparrows:before {\n    font-family: \\\"pxli\\\";\n    font-size: ##icon-size##px;\n    font-style: normal;\n    font-weight: bold;\n	text-align: center;\n  	color: inherit;\n}\n.theme-custom.tparrows.tp-leftarrow:before {\n	content: \\\"\\\\e959\\\";\n}\n.theme-custom.tparrows.tp-rightarrow:before {\n	content: \\\"\\\\e95a\\\";\n}\n\n','','{\"dim\":{\"width\":\"160\",\"height\":\"160\"},\"placeholders\":{\"width\":{\"type\":\"custom\",\"title\":\"Width\",\"data\":\"60\"},\"height\":{\"type\":\"custom\",\"title\":\"Height\",\"data\":\"140\"},\"icon-size\":{\"type\":\"custom\",\"title\":\"Icon Size\",\"data\":\"18\"},\"background\":{\"type\":\"color\",\"title\":\"Background Color\",\"data\":\"rgba(255, 255, 255, 0.2)\"},\"hover_bg\":{\"type\":\"color\",\"title\":\"Hover Background\",\"data\":\"#ad9779\"},\"hover_color\":{\"type\":\"color\",\"title\":\"Hover Icon Color\",\"data\":\"#ffffff\"},\"icon_color\":{\"type\":\"color\",\"title\":\"Icon Color\",\"data\":\"#ffffff\"}},\"presets\":\"\",\"version\":\"6.0.0\"}'),
(2,'Theme Custom','theme-custom','bullets','.theme-custom {\n  position: relative;\n}\n@media screen and (max-width: 1023px){\n    .theme-custom.tp-bullets{\n        transform: translate(25px, -60px) !important;\n    }\n}\n.theme-custom .tp-bullet {\n  background: none !important;\n}\n.theme-custom .tp-bullet .number-wrap {\n  display: flex;\n  align-items: center;\n}\n.theme-custom .tp-bullet .number-wrap .slider-index{\n  padding: 4px 6px;\n  position: relative;\n}\n.theme-custom .tp-bullet .number-wrap .slider-index:after{\n  content: \\\"\\\";\n  display: block;\n  height:2px;\n  width: 0;\n  background-color: transparent;\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  transition: all 300ms linear 0s;\n}\n.theme-custom .tp-bullet .number-wrap .slider-index span {\n  font-size: 16px;\n  font-family: \\\'Nunito Sans\\\', sans-serif;\n  color: ##bullet-color##;\n  position: relative;\n}\n.theme-custom .tp-bullet.selected .number-wrap .slider-index:after{\n  background-color: ##bullet-hover##;\n  width:100%;\n}','<div class=\\\"number-wrap\\\">\n  <span class=\\\"slider-index\\\"><span>{{param1}}</span></span>\n</div>','{\"dim\":{\"width\":\"160\",\"height\":\"160\"},\"placeholders\":{\"bullet-color\":{\"title\":\"Bullet-Color\",\"type\":\"color\",\"data\":\"rgba(255, 255, 255, 0.5)\"},\"bullet-hover\":{\"title\":\"Hover-Bullet\",\"type\":\"color\",\"data\":\"#ffffff\"}},\"presets\":\"\",\"version\":\"6.0.0\"}');
